/* WINDOWKILL backend — SQLite storage layer (node:sqlite, zero dependencies)
 *
 * SEC-01/B1: profiles carry a `token_hash` column (sha256 of the profile
 * token). The raw token is generated by the server layer, shown to the client
 * exactly once at creation time and NEVER stored or returned afterwards.
 *
 * B7: schema changes go through versioned migrations keyed on
 * `PRAGMA user_version` (see MIGRATIONS below), so a new build can upgrade a
 * database file that already lives on a persistent volume.
 */
"use strict";
import { createHash, randomBytes } from "node:crypto";
import { DatabaseSync } from "node:sqlite";

export const DIFFICULTIES = ["chill", "normal", "hard"];

/** sha256 hex of a profile token — the only form ever persisted. */
export function hashProfileToken(token) {
  return createHash("sha256").update(String(token)).digest("hex");
}

function columnNames(db, table) {
  return db.prepare(`PRAGMA table_info(${table})`).all().map((r) => r.name);
}

/* Versioned migrations. Each entry upgrades the schema TO its version and
 * runs exactly once per database file, in order, inside a transaction.
 * Migration 1 predates versioning in spirit: databases created by the old
 * code have user_version = 0 but already contain the base tables, so the
 * migration is written defensively (add the column only if missing). */
/* Season 1 schema (shared by fresh-boot DDL and migration 2). Two parallel
 * leaderboards (SEASON-1-DECISIONS.md Q2b-A): `scores` stays the all-time
 * board (never reset); `season_scores` is the seasonal board, keyed by
 * `seasons.id` so a season rollover just swaps the active row — no data is
 * ever deleted. DAILY_MODS naming keeps daily-season ids separate from the
 * M9/M10 chain-popup ids (design constraint). */
const SEASON_SCHEMA = `
  CREATE TABLE IF NOT EXISTS seasons (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    start_at INTEGER NOT NULL,
    end_at INTEGER,
    status TEXT NOT NULL DEFAULT 'upcoming' CHECK (status IN ('upcoming', 'active', 'ended'))
  );
  CREATE TABLE IF NOT EXISTS season_scores (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    season_id TEXT NOT NULL REFERENCES seasons(id) ON DELETE CASCADE,
    profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    score INTEGER NOT NULL,
    wave INTEGER NOT NULL,
    kills INTEGER NOT NULL,
    duration_ms INTEGER NOT NULL,
    difficulty TEXT NOT NULL,
    created_at INTEGER NOT NULL
  );
  CREATE INDEX IF NOT EXISTS idx_season_scores_board ON season_scores (season_id, difficulty, score DESC, created_at ASC);
  CREATE INDEX IF NOT EXISTS idx_season_scores_profile ON season_scores (season_id, profile_id);
`;

const MIGRATIONS = [
  {
    version: 1,
    up(db) {
      // SEC-01: per-profile auth token hash (NULL = legacy profile, no token yet).
      if (!columnNames(db, "profiles").includes("token_hash")) {
        db.exec("ALTER TABLE profiles ADD COLUMN token_hash TEXT");
      }
    },
  },
  {
    version: 2,
    up(db, opts = {}) {
      // Season 1: seasons + season_scores (forward-only; old DBs just gain tables).
      db.exec(SEASON_SCHEMA);
      // Minimal current-season seed: exactly one active season. Configurable
      // via openDb opts (server/config.js: WK_SEASON_ID / WK_SEASON_NAME /
      // WK_SEASON_DAYS). Skipped if any season is already active.
      const seed = opts.seedSeason || {};
      const id = typeof seed.id === "string" && seed.id ? seed.id : "S1";
      const name = typeof seed.name === "string" && seed.name ? seed.name : "Season 1 — Mùa Deadline";
      const days = Number.isInteger(seed.days) && seed.days > 0 ? seed.days : 42;
      const hasActive = db.prepare("SELECT 1 FROM seasons WHERE status = 'active' LIMIT 1").get();
      if (!hasActive) {
        const now = Date.now();
        db.prepare(
          "INSERT OR IGNORE INTO seasons (id, name, start_at, end_at, status) VALUES (?, ?, ?, ?, 'active')"
        ).run(id, name, now, now + days * 24 * 3600_000);
      }
    },
  },
];

function runMigrations(db, opts = {}) {
  const row = db.prepare("PRAGMA user_version").get();
  let current = row ? Number(row.user_version) || 0 : 0;
  for (const m of MIGRATIONS) {
    if (m.version <= current) continue;
    db.exec("BEGIN");
    try {
      m.up(db, opts);
      db.exec(`PRAGMA user_version = ${m.version}`);
      db.exec("COMMIT");
      current = m.version;
    } catch (e) {
      db.exec("ROLLBACK");
      throw e;
    }
  }
  return current;
}

export function openDb(dbPath, opts = {}) {
  const db = new DatabaseSync(dbPath);
  const eventsCap = Number.isInteger(opts.eventsCap) && opts.eventsCap > 0 ? opts.eventsCap : 100_000;
  const errorsCap = Number.isInteger(opts.errorsCap) && opts.errorsCap > 0 ? opts.errorsCap : 500;
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec("PRAGMA foreign_keys = ON;");
  db.exec(`
    CREATE TABLE IF NOT EXISTS profiles (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      emoji TEXT NOT NULL DEFAULT '🎮',
      created_at INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS scores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
      score INTEGER NOT NULL,
      wave INTEGER NOT NULL,
      kills INTEGER NOT NULL,
      duration_ms INTEGER NOT NULL,
      difficulty TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_scores_leaderboard ON scores (difficulty, score DESC, created_at ASC);
    CREATE INDEX IF NOT EXISTS idx_scores_profile ON scores (profile_id);
    /* Privacy-friendly analytics events. Only aggregates are ever read back;
       the raw profile id is never stored (clients send a sha256 hash). */
    CREATE TABLE IF NOT EXISTS events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      type TEXT NOT NULL,
      profile_hash TEXT,
      difficulty TEXT,
      score INTEGER,
      wave INTEGER,
      payload TEXT NOT NULL DEFAULT '{}',
      ts INTEGER NOT NULL,
      received_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_events_type_ts ON events (type, ts);
    CREATE INDEX IF NOT EXISTS idx_events_profile_ts ON events (profile_hash, ts);
    /* Client-side error reports (message + source only, no stack, no PII). */
    CREATE TABLE IF NOT EXISTS errors (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      message TEXT NOT NULL,
      source TEXT NOT NULL DEFAULT '',
      profile_hash TEXT,
      ts INTEGER NOT NULL,
      received_at INTEGER NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_errors_ts ON errors (ts);
    /* Season 1: seasons + season_scores — the seasonal leaderboard board.
       Defined in SEASON_SCHEMA above; included here so fresh DBs carry it
       even before migrations run, and by migration 2 for existing DBs. */
  `);
  db.exec(SEASON_SCHEMA);
  // B7: apply versioned migrations BEFORE preparing statements that may
  // reference migrated columns (token_hash).
  runMigrations(db, opts);

  const q = {
    insertProfile: db.prepare("INSERT INTO profiles (id, name, emoji, created_at, token_hash) VALUES (?, ?, ?, ?, ?)"),
    getProfile: db.prepare("SELECT id, name, emoji, created_at AS createdAt FROM profiles WHERE id = ?"),
    getTokenHash: db.prepare("SELECT token_hash AS tokenHash FROM profiles WHERE id = ?"),
    setTokenHash: db.prepare("UPDATE profiles SET token_hash = ? WHERE id = ?"),
    listProfiles: db.prepare("SELECT id, name, emoji, created_at AS createdAt FROM profiles ORDER BY created_at ASC"),
    deleteProfile: db.prepare("DELETE FROM profiles WHERE id = ?"),
    ping: db.prepare("SELECT 1 AS one"),
    insertScore: db.prepare(
      "INSERT INTO scores (profile_id, score, wave, kills, duration_ms, difficulty, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ),
    /* Season 1 — seasonal board. Every score is ALSO written to `scores`
     * (the all-time board); the season copy is opt-in via `seasonId` on
     * the submit body (the client only sends it for Boss-rush "Đấu Sếp"
     * and Daily runs, per SEASON-1-DECISIONS.md §2.4/§3). */
    insertSeasonScore: db.prepare(
      "INSERT INTO season_scores (season_id, profile_id, score, wave, kills, duration_ms, difficulty, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
    ),
    getSeason: db.prepare("SELECT id, name, start_at AS startAt, end_at AS endAt, status FROM seasons WHERE id = ?"),
    getActiveSeason: db.prepare(
      "SELECT id, name, start_at AS startAt, end_at AS endAt, status FROM seasons WHERE status = 'active' ORDER BY start_at DESC LIMIT 1"
    ),
    seasonalLeaderboard: db.prepare(`
      SELECT s.score, s.wave, s.kills, s.duration_ms AS durationMs, s.difficulty,
             s.created_at AS createdAt, p.id AS profileId, p.name AS profileName, p.emoji AS profileEmoji
      FROM season_scores s JOIN profiles p ON p.id = s.profile_id
      WHERE s.season_id = ? AND s.difficulty = ?
      ORDER BY s.score DESC, s.created_at ASC
      LIMIT ?
    `),
    leaderboard: db.prepare(`
      SELECT s.score, s.wave, s.kills, s.duration_ms AS durationMs, s.difficulty,
             s.created_at AS createdAt, p.id AS profileId, p.name AS profileName, p.emoji AS profileEmoji
      FROM scores s JOIN profiles p ON p.id = s.profile_id
      WHERE s.difficulty = ?
      ORDER BY s.score DESC, s.created_at ASC
      LIMIT ?
    `),
    bestPerDifficulty: db.prepare(`
      SELECT difficulty, MAX(score) AS bestScore, MAX(wave) AS bestWave
      FROM scores WHERE profile_id = ? GROUP BY difficulty
    `),
    statsAgg: db.prepare(`
      SELECT COUNT(*) AS games, COALESCE(SUM(kills), 0) AS kills,
             COALESCE(SUM(score), 0) AS totalScore, COALESCE(MAX(wave), 0) AS bestWave,
             COALESCE(SUM(duration_ms), 0) AS totalDurationMs
      FROM scores WHERE profile_id = ?
    `),
    insertEvent: db.prepare(`
      INSERT INTO events (type, profile_hash, difficulty, score, wave, payload, ts, received_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `),
    trimEvents: db.prepare("DELETE FROM events WHERE id <= (SELECT COALESCE(MAX(id), 0) - ? FROM events)"),
    insertError: db.prepare(`
      INSERT INTO errors (message, source, profile_hash, ts, received_at)
      VALUES (?, ?, ?, ?, ?)
    `),
    trimErrors: db.prepare("DELETE FROM errors WHERE id <= (SELECT COALESCE(MAX(id), 0) - ? FROM errors)"),
    errorCount: db.prepare("SELECT COUNT(*) AS n FROM errors"),
    /* Sprint Round 2 — inputs for /api/metrics/summary (see metricsSummary). */
    s2Sessions: db.prepare(`
      SELECT COUNT(*) AS sessions, COUNT(DISTINCT profile_hash) AS users
      FROM events WHERE (type = 'game_start' OR type = 'session_start') AND ts >= ?
    `),
    s2CtaClicks: db.prepare("SELECT COUNT(*) AS n FROM events WHERE type = 'cta_click' AND ts >= ?"),
    s2Deaths: db.prepare("SELECT wave, payload FROM events WHERE type = 'death_cause' AND ts >= ?"),
    /* First session ever per profile, restricted to profiles active in the
     * last 7 days (D1 cohort needs the TRUE first session, not first-in-window). */
    s2CohortFirst: db.prepare(`
      SELECT profile_hash, MIN(ts) AS first_ts
      FROM events
      WHERE (type = 'game_start' OR type = 'session_start') AND profile_hash IS NOT NULL
      GROUP BY profile_hash
      HAVING SUM(CASE WHEN ts >= ? THEN 1 ELSE 0 END) > 0
    `),
    s2SessionDays: db.prepare(`
      SELECT profile_hash, ts FROM events
      WHERE (type = 'game_start' OR type = 'session_start')
        AND profile_hash IS NOT NULL AND ts >= ?
    `),
    s2Traffic: db.prepare(`
      SELECT payload FROM events
      WHERE (type = 'game_start' OR type = 'session_start' OR type = 'cta_click') AND ts >= ?
    `),
    dau: db.prepare(`
      SELECT COUNT(DISTINCT profile_hash) AS n FROM events
      WHERE ts >= ? AND profile_hash IS NOT NULL
    `),
    gamesAgg: db.prepare(`
      SELECT COUNT(*) AS games,
             COALESCE(AVG(score), 0) AS avgScore,
             COALESCE(MAX(wave), 0) AS bestWave
      FROM events WHERE type = 'game_over' AND ts >= ?
    `),
    gamesByDiff: db.prepare(`
      SELECT difficulty, COUNT(*) AS games,
             COALESCE(AVG(score), 0) AS avgScore,
             COALESCE(MAX(wave), 0) AS bestWave
      FROM events WHERE type = 'game_over' AND ts >= ?
      GROUP BY difficulty
    `),
  };

  const now = () => Date.now();

  return {
    db,
    /* tokenHash: sha256 hex of the one-time token, or null for legacy rows. */
    createProfile({ id, name, emoji, tokenHash = null }) {
      const pid = id || "srv_" + randomBytes(8).toString("hex");
      q.insertProfile.run(pid, name, emoji || "🎮", now(), tokenHash);
      return q.getProfile.get(pid);
    },
    getProfile: (id) => q.getProfile.get(id) || null,
    /* Auth internals — the hash never leaves the server layer. */
    getProfileTokenHash: (id) => {
      const r = q.getTokenHash.get(id);
      return r ? r.tokenHash ?? null : null;
    },
    setProfileTokenHash: (id, tokenHash) => q.setTokenHash.run(tokenHash, id).changes > 0,
    listProfiles: () => q.listProfiles.all(),
    deleteProfile: (id) => q.deleteProfile.run(id).changes > 0,
    /* Readiness probe for /api/health (B13): throws if the DB is dead. */
    ping: () => q.ping.get(),
    addScore({ profileId, score, wave, kills, durationMs, difficulty, seasonId }) {
      const r = q.insertScore.run(profileId, score, wave, kills, durationMs, difficulty, now());
      const out = { id: Number(r.lastInsertRowid) };
      // Season 1: opt-in seasonal copy (client gates this to Đấu Sếp / Daily runs).
      if (seasonId) {
        const rs = q.insertSeasonScore.run(seasonId, profileId, score, wave, kills, durationMs, difficulty, now());
        out.seasonScoreId = Number(rs.lastInsertRowid);
        out.seasonId = seasonId;
      }
      return out;
    },
    leaderboard: (difficulty, limit) => q.leaderboard.all(difficulty, limit),
    /* Season 1 — season lookups + the seasonal board. Row shape matches
     * /api/leaderboard exactly (score, wave, kills, durationMs, difficulty,
     * createdAt, profileId, profileName, profileEmoji). */
    getSeason: (id) => q.getSeason.get(id) || null,
    getActiveSeason: () => q.getActiveSeason.get() || null,
    seasonalLeaderboard: (seasonId, difficulty, limit) => q.seasonalLeaderboard.all(seasonId, difficulty, limit),
    profileStats(profileId) {
      const agg = q.statsAgg.get(profileId);
      const best = {};
      for (const row of q.bestPerDifficulty.all(profileId)) {
        best[row.difficulty] = { score: row.bestScore, wave: row.bestWave };
      }
      return {
        games: agg.games,
        kills: agg.kills,
        totalScore: agg.totalScore,
        bestWave: agg.bestWave,
        totalDurationMs: agg.totalDurationMs,
        bestPerDifficulty: best,
      };
    },
    /* Analytics: insert a batch of validated events (payload holds the
       validated per-type extras; score/wave/difficulty are extracted for
       cheap aggregation). Old rows are trimmed past eventsCap. */
    addEvents(events) {
      const t = now();
      for (const e of events) {
        q.insertEvent.run(
          e.type, e.profile_id_hash || null, e.difficulty || null,
          e.score ?? null, e.wave ?? null,
          JSON.stringify(e.payload || {}), e.ts, t
        );
      }
      q.trimEvents.run(eventsCap);
      return { inserted: events.length };
    },
    /* Error reports: capped at errorsCap rows (oldest trimmed). */
    addErrors(errors) {
      const t = now();
      for (const e of errors) {
        q.insertError.run(e.message, e.source || "", e.profile_id_hash || null, e.ts, t);
      }
      q.trimErrors.run(errorsCap);
      return { inserted: errors.length, stored: q.errorCount.get().n };
    },
    errorCount: () => q.errorCount.get().n,
    /* Internal dashboard aggregates (privacy-friendly: counts & averages only). */
    metrics() {      const t = now();
      const day = t - 24 * 3600_000;
      const week = t - 7 * 24 * 3600_000;
      const agg = q.gamesAgg.get(week);
      const byDiff = {};
      for (const row of q.gamesByDiff.all(week)) {
        byDiff[row.difficulty] = {
          games: row.games,
          avgScore: Math.round(row.avgScore * 10) / 10,
          bestWave: row.bestWave,
        };
      }
      return {
        dau: q.dau.get(day).n,
        games7d: agg.games,
        avgScore7d: Math.round(agg.avgScore * 10) / 10,
        bestWave7d: agg.bestWave,
        byDifficulty7d: byDiff,
        generatedAt: t,
      };
    },
    /* Sprint Round 2 — the 5 baseline metrics (see server/README.md
     * "Metrics Baseline (Sprint Round 2)"). All inputs are aggregates over
     * the privacy-friendly events table; no PII is ever returned.
     *
     * Windows: 30 days for conversion/wave/traffic, 7 days for
     * runs-per-user, 7-day D1 cohort. A metric with no data reports null
     * (rate/value) instead of dividing by zero; `healthy` is then null. */
    metricsSummary() {
      const t = now();
      const day = 24 * 3600_000;
      const w30 = t - 30 * day;
      const w14 = t - 14 * day;
      const w7 = t - 7 * day;

      // 1. web→desktop conversion = cta_clicks / game sessions (30d), healthy ≥3%
      const s30 = q.s2Sessions.get(w30);
      const clicks = q.s2CtaClicks.get(w30).n;
      const conversionRate = s30.sessions > 0 ? clicks / s30.sessions : null;

      // 2. D1 retention: cohort = profiles whose FIRST EVER session was 1–7
      // days ago (old enough for a D+1); retained = active on day(first)+1.
      const dayRows = q.s2SessionDays.all(w14);
      const activeDays = new Map();
      for (const r of dayRows) {
        let set = activeDays.get(r.profile_hash);
        if (!set) { set = new Set(); activeDays.set(r.profile_hash, set); }
        set.add(Math.floor(r.ts / day));
      }
      let cohort = 0, retained = 0;
      for (const r of q.s2CohortFirst.all(w7)) {
        const firstTs = r.first_ts;
        if (firstTs < w7 || firstTs > t - day) continue; // too old, or D1 not observable yet
        cohort++;
        const d1 = Math.floor(firstTs / day) + 1;
        const set = activeDays.get(r.profile_hash);
        if (set && set.has(d1)) retained++;
      }
      const d1Rate = cohort > 0 ? retained / cohort : null;

      // 3. wave_gameover distribution: death_cause waves (30d).
      const deaths = q.s2Deaths.all(w30);
      const waves = deaths.map((d) => d.wave).filter((w) => Number.isInteger(w)).sort((a, b) => a - b);
      const median = waves.length
        ? (waves.length % 2 ? waves[(waves.length - 1) / 2]
           : (waves[waves.length / 2 - 1] + waves[waves.length / 2]) / 2)
        : null;
      const buckets = { "1-4": 0, "5-9": 0, "10-14": 0, "15-19": 0, "20-24": 0, "25+": 0 };
      for (const w of waves) {
        if (w <= 4) buckets["1-4"]++;
        else if (w <= 9) buckets["5-9"]++;
        else if (w <= 14) buckets["10-14"]++;
        else if (w <= 19) buckets["15-19"]++;
        else if (w <= 24) buckets["20-24"]++;
        else buckets["25+"]++;
      }
      const byCause = {};
      for (const d of deaths) {
        try {
          const c = JSON.parse(d.payload || "{}").cause;
          if (typeof c === "string") byCause[c] = (byCause[c] || 0) + 1;
        } catch {}
      }

      // 4. runs per user per week = sessions / distinct profiles (7d), healthy ≥2
      const s7 = q.s2Sessions.get(w7);
      const runsPerUser = s7.users > 0 ? s7.sessions / s7.users : null;

      // 5. traffic sources: utm_source/utm distribution over sessions+clicks (30d).
      const traffic = {};
      for (const r of q.s2Traffic.all(w30)) {
        try {
          const p = JSON.parse(r.payload || "{}");
          const src = p.utm_source || p.utm;
          if (typeof src === "string" && src) traffic[src] = (traffic[src] || 0) + 1;
        } catch {}
      }

      const healthy = (rate, threshold) =>
        rate === null ? null : rate >= threshold;

      return {
        windowDays: 30,
        generatedAt: t,
        conversion: {
          ctaClicks: clicks, sessions: s30.sessions,
          rate: conversionRate === null ? null : Math.round(conversionRate * 1000) / 1000,
          healthy: healthy(conversionRate, 0.03),
        },
        d1Retention: {
          cohort, retained,
          rate: d1Rate === null ? null : Math.round(d1Rate * 1000) / 1000,
          healthy: healthy(d1Rate, 0.15),
        },
        waveGameover: {
          deaths: waves.length,
          medianWave: median,
          buckets, byCause,
          healthy: healthy(median, 8),
        },
        runsPerUserWeek: {
          sessions: s7.sessions, users: s7.users,
          value: runsPerUser === null ? null : Math.round(runsPerUser * 100) / 100,
          healthy: healthy(runsPerUser, 2),
        },
        trafficSources: traffic,
        thresholds: {
          conversion: 0.03, d1Retention: 0.15,
          medianWaveGameover: 8, runsPerUserWeek: 2,
        },
      };
    },
    close: () => db.close(),
  };
}
